insert into public.lr_robot_catalog(id,name,robot_type,rarity,description,asset,color,price_minor,currency,daily_rc_minor,lifetime_days,max_battles,attack,defense,health,identity) values('moss','BROTTO','explorer','Comum','Encontrado entre raízes e placas esquecidas, Brotto aprendeu a transformar pequenos sinais em novas rotas. Seu núcleo verde alimenta uma produção constante enquanto ele protege os primeiros passos da equipe.','moss-sprites.png','#bddf91',30000,'LC',3000,7,24,24,20,110,'{"id": "moss", "name": "BROTTO", "type": "explorer", "rarity": "Comum", "description": "Encontrado entre raízes e placas esquecidas, Brotto aprendeu a transformar pequenos sinais em novas rotas. Seu núcleo verde alimenta uma produção constante enquanto ele protege os primeiros passos da equipe.", "price": 300, "currency": "LC", "daily": 30, "lifetime": 7, "maxBattles": 24, "attack": 24, "defense": 20, "health": 110, "asset": "moss-sprites.png", "color": "#bddf91", "serial": "EX-01", "subtitle": "O despertar da floresta", "signature": "Raízes de energia", "slots": ["core", "arm", "shield"], "soundPitch": 1.02, "combatStyle": "organic", "animationAsset": "moss-combat-v6.png"}'::jsonb) on conflict(id) do update set name=excluded.name,robot_type=excluded.robot_type,rarity=excluded.rarity,description=excluded.description,asset=excluded.asset,color=excluded.color,price_minor=excluded.price_minor,currency=excluded.currency,daily_rc_minor=excluded.daily_rc_minor,lifetime_days=excluded.lifetime_days,max_battles=excluded.max_battles,attack=excluded.attack,defense=excluded.defense,health=excluded.health,identity=excluded.identity;
