insert into public.lr_robot_catalog(id,name,robot_type,rarity,description,asset,color,price_minor,currency,daily_rc_minor,lifetime_days,max_battles,attack,defense,health,identity) values('abyss','NAUTILUS','explorer','Épico','Um sino de mergulho que aprendeu a sonhar. Nautilus caminha com tentáculos articulados, lê ecos nas ruínas submersas e transforma pressão em energia para seu pulso abissal.','abyss-combat-v7.png','#90dcf6',410000,'LC',46000,42,190,76,62,300,'{"id": "abyss", "name": "NAUTILUS", "type": "explorer", "rarity": "Épico", "subtitle": "O cartógrafo do silêncio", "serial": "NTL-11", "signature": "Há luz até onde o mapa termina.", "description": "Um sino de mergulho que aprendeu a sonhar. Nautilus caminha com tentáculos articulados, lê ecos nas ruínas submersas e transforma pressão em energia para seu pulso abissal.", "price": 4100, "daily": 460, "lifetime": 42, "maxBattles": 190, "attack": 76, "defense": 62, "health": 300, "color": "#90dcf6", "combatStyle": "orbital", "soundPitch": 0.83, "currency": "LC", "asset": "abyss-combat-v7.png", "animationAsset": "abyss-combat-v7.png", "slots": ["core", "arm", "shield", "booster", "sensor"], "maxLevel": 10}'::jsonb) on conflict(id) do update set name=excluded.name,robot_type=excluded.robot_type,rarity=excluded.rarity,description=excluded.description,asset=excluded.asset,color=excluded.color,price_minor=excluded.price_minor,currency=excluded.currency,daily_rc_minor=excluded.daily_rc_minor,lifetime_days=excluded.lifetime_days,max_battles=excluded.max_battles,attack=excluded.attack,defense=excluded.defense,health=excluded.health,identity=excluded.identity;
