insert into public.lr_story_chapters(id,title,place,story,required_power,reward_rc_minor,active,definition) values(1,'O despertar','Arredores do hangar','Após décadas de silêncio, um pequeno robô desperta. Uma transmissão distante pede ajuda. Siga o sinal.',25,12000,true,'{"id": 1, "title": "O despertar", "place": "Arredores do hangar", "reward": 120, "power": 25, "story": "Após décadas de silêncio, um pequeno robô desperta. Uma transmissão distante pede ajuda. Siga o sinal.", "objective": "Vença os guardiões de Arredores do hangar e libere o próximo sinal.", "conclusion": "O sinal de Arredores do hangar está seguro. Sua equipe abriu uma nova passagem.", "enabled": true, "scene": "aurora", "enemies": [{"robotId": "moss", "name": "Vigia de sucata"}, {"robotId": "moss", "name": "Sentinela enferrujada"}]}'::jsonb) on conflict(id) do update set title=excluded.title,place=excluded.place,story=excluded.story,required_power=excluded.required_power,reward_rc_minor=excluded.reward_rc_minor,active=excluded.active,definition=excluded.definition;
insert into public.lr_story_chapters(id,title,place,story,required_power,reward_rc_minor,active,definition) values(2,'Entre as raízes','Floresta de circuitos','A natureza tomou os antigos circuitos. Encontre uma rota entre as raízes e reative o primeiro farol.',38,18000,true,'{"id": 2, "title": "Entre as raízes", "place": "Floresta de circuitos", "reward": 180, "power": 38, "story": "A natureza tomou os antigos circuitos. Encontre uma rota entre as raízes e reative o primeiro farol.", "objective": "Vença os guardiões de Floresta de circuitos e libere o próximo sinal.", "conclusion": "O sinal de Floresta de circuitos está seguro. Sua equipe abriu uma nova passagem.", "enabled": true, "scene": "roots", "enemies": [{"robotId": "moss", "name": "Rastreador de raízes"}, {"robotId": "volt", "name": "Caçador de sinais"}]}'::jsonb) on conflict(id) do update set title=excluded.title,place=excluded.place,story=excluded.story,required_power=excluded.required_power,reward_rc_minor=excluded.reward_rc_minor,active=excluded.active,definition=excluded.definition;
insert into public.lr_story_chapters(id,title,place,story,required_power,reward_rc_minor,active,definition) values(3,'Cidade esquecida','Distrito Aurora','O distrito está vazio, mas suas máquinas ainda se movem. Uma patrulha protege o caminho até o núcleo.',52,26000,true,'{"id": 3, "title": "Cidade esquecida", "place": "Distrito Aurora", "reward": 260, "power": 52, "story": "O distrito está vazio, mas suas máquinas ainda se movem. Uma patrulha protege o caminho até o núcleo.", "objective": "Vença os guardiões de Distrito Aurora e libere o próximo sinal.", "conclusion": "O sinal de Distrito Aurora está seguro. Sua equipe abriu uma nova passagem.", "enabled": true, "scene": "city", "enemies": [{"robotId": "volt", "name": "Patrulha Aurora"}, {"robotId": "moss", "name": "Vigia do distrito"}, {"robotId": "volt", "name": "Comandante Aurora"}]}'::jsonb) on conflict(id) do update set title=excluded.title,place=excluded.place,story=excluded.story,required_power=excluded.required_power,reward_rc_minor=excluded.reward_rc_minor,active=excluded.active,definition=excluded.definition;
insert into public.lr_story_chapters(id,title,place,story,required_power,reward_rc_minor,active,definition) values(4,'O guardião','Portão de aço','Um guardião antigo bloqueia a entrada. Sua força será testada antes de avançar.',65,34000,true,'{"id": 4, "title": "O guardião", "place": "Portão de aço", "reward": 340, "power": 65, "story": "Um guardião antigo bloqueia a entrada. Sua força será testada antes de avançar.", "objective": "Vença os guardiões de Portão de aço e libere o próximo sinal.", "conclusion": "O sinal de Portão de aço está seguro. Sua equipe abriu uma nova passagem.", "enabled": true, "scene": "steel", "enemies": [{"robotId": "moss", "name": "Vigia do portão"}, {"robotId": "volt", "name": "Artilheiro antigo"}, {"robotId": "titan", "name": "Guardião de aço"}]}'::jsonb) on conflict(id) do update set title=excluded.title,place=excluded.place,story=excluded.story,required_power=excluded.required_power,reward_rc_minor=excluded.reward_rc_minor,active=excluded.active,definition=excluded.definition;
insert into public.lr_story_chapters(id,title,place,story,required_power,reward_rc_minor,active,definition) values(5,'Além do horizonte','Vale das antenas','O sinal ganha força. Na linha do horizonte, uma nova comunidade de robôs começa a surgir.',80,48000,true,'{"id": 5, "title": "Além do horizonte", "place": "Vale das antenas", "reward": 480, "power": 80, "story": "O sinal ganha força. Na linha do horizonte, uma nova comunidade de robôs começa a surgir.", "objective": "Vença os guardiões de Vale das antenas e libere o próximo sinal.", "conclusion": "O sinal de Vale das antenas está seguro. Sua equipe abriu uma nova passagem.", "enabled": true, "scene": "sunset", "enemies": [{"robotId": "volt", "name": "Patrulha do vale"}, {"robotId": "volt", "name": "Interceptor de antenas"}, {"robotId": "titan", "name": "Guardião do farol"}]}'::jsonb) on conflict(id) do update set title=excluded.title,place=excluded.place,story=excluded.story,required_power=excluded.required_power,reward_rc_minor=excluded.reward_rc_minor,active=excluded.active,definition=excluded.definition;
insert into public.lr_story_chapters(id,title,place,story,required_power,reward_rc_minor,active,definition) values(6,'Uma nova vida','Núcleo da cidade','O núcleo adormecido pode devolver energia a toda a região. Esta é a hora de reacender o futuro.',100,65000,true,'{"id": 6, "title": "Uma nova vida", "place": "Núcleo da cidade", "reward": 650, "power": 100, "story": "O núcleo adormecido pode devolver energia a toda a região. Esta é a hora de reacender o futuro.", "objective": "Vença os guardiões de Núcleo da cidade e libere o próximo sinal.", "conclusion": "O sinal de Núcleo da cidade está seguro. Sua equipe abriu uma nova passagem.", "enabled": true, "scene": "core", "enemies": [{"robotId": "moss", "name": "Vigia do núcleo"}, {"robotId": "volt", "name": "Interceptor quântico"}, {"robotId": "titan", "name": "Titã do núcleo"}]}'::jsonb) on conflict(id) do update set title=excluded.title,place=excluded.place,story=excluded.story,required_power=excluded.required_power,reward_rc_minor=excluded.reward_rc_minor,active=excluded.active,definition=excluded.definition;
