insert into public.lr_settings(key,value,visibility) values('economy','{"audio": {"music": true, "tempo": 84, "theme": "aurora", "effects": true, "enabled": true, "musicVolume": 0.3, "masterVolume": 0.45, "effectsVolume": 0.65}, "rules": {"actionMs": 600, "travelMs": 2400, "damageMin": 7, "energyMax": 3, "randomBase": 0.8, "autoDelayMs": 650, "betweenWavesMs": 1800, "randomVariance": 0.3, "retaliationMin": 5, "levelAttackStep": 3, "levelHealthStep": 10, "shieldReduction": 0.4, "storyBaseHealth": 52, "waveHealPercent": 35, "attackMultiplier": 1.05, "levelDefenseStep": 2, "defenseAbsorption": 0.28, "specialMultiplier": 1.9, "storyAttackPercent": 43, "storyDefensePercent": 22, "storyHealthPerChapter": 14, "storyWaveScalePercent": 8, "productionLevelPercent": 10, "shieldAttackMultiplier": 0.55, "storyBossHealthPercent": 118, "playerDefenseAbsorption": 0.22, "partProductionLevelPercent": 15}, "rcPerLC": 10, "passCost": 80, "lcPerReal": 100, "levelCost": 120, "battleLoss": 30, "replayCost": 40, "commissions": [5, 2, 1], "freeBattles": 4, "minWithdraw": 10, "withdrawFee": 0, "battleReward": 80, "maxPartLevel": 10, "maxRobotLevel": 10, "tutorialBonus": 300, "autoStoryStart": false, "replayCurrency": "RC", "autoWithdrawals": false, "autoWithdrawalMax": 50, "matchTimeoutSeconds": 8, "productionMultiplier": 10, "principalReturnPercent": 100}'::jsonb,'public') on conflict(key) do update set value=excluded.value;
insert into public.lr_settings(key,value,visibility) values('seasons','[{"id": "awakening", "to": 6, "from": 1, "intro": "Sou NEXA, a memória do hangar. Nossos faróis se apagaram há muito tempo. Comece pelos arredores, vença as patrulhas e reúna energia para reacender Aurora.", "scene": "roots", "title": "A era do despertar", "number": 1, "subtitle": "Um sinal. Uma cidade. Um novo começo.", "musicTempo": 92, "musicTheme": "verdant", "combatTempo": 116, "combatTheme": "verdant-duel", "guideRobotId": "moss", "customMusicUrl": "", "customCombatMusicUrl": ""}, {"id": "frontiers", "to": 12, "from": 7, "intro": "Aurora voltou a brilhar, mas o sinal veio de mais longe. A forja rubra, a câmara glacial e o farol celeste escondem partes do mesmo mapa. Prepare equipamentos para atravessar os três setores.", "scene": "ember", "title": "As fronteiras de Aurora", "number": 2, "subtitle": "Do fogo ao gelo, rumo às nuvens.", "musicTempo": 104, "musicTheme": "frontier", "combatTempo": 128, "combatTheme": "frontier-duel", "guideRobotId": "nimbus", "customMusicUrl": "", "customCombatMusicUrl": ""}, {"id": "stars", "to": 18, "from": 13, "intro": "As coordenadas levam à estação Horizonte. Os guardiões do prisma e da obsidiana protegem o Santuário Life. Evolua sua equipe; o último farol espera por você.", "scene": "space", "title": "Além das estrelas", "number": 3, "subtitle": "A última transmissão atravessa o universo.", "musicTempo": 82, "musicTheme": "starlight", "combatTempo": 122, "combatTheme": "starlight-duel", "guideRobotId": "orbit", "customMusicUrl": "", "customCombatMusicUrl": ""}, {"id": "coral", "to": 26, "from": 19, "intro": "NEXA: O sinal agora pulsa sob as ondas. Corallis conhece os jardins de coral e Nautilus ouviu um chamado na fossa. Repare as comportas, atravesse as ruínas e devolva voz ao farol submerso.", "scene": "coral", "title": "Abissos de Coral", "number": 4, "subtitle": "O oceano guarda um farol que nunca se apagou.", "musicTempo": 88, "musicTheme": "tides", "combatTempo": 118, "combatTheme": "tides-duel", "guideRobotId": "abyss", "customMusicUrl": "", "customCombatMusicUrl": ""}, {"id": "clockwork", "to": 34, "from": 27, "intro": "NEXA: A torre repete o mesmo minuto. Ticton protege seu coração, mas alguém roubou a engrenagem da aurora. Siga Vésper pelos telhados, sincronize os pêndulos e liberte o próximo instante.", "scene": "clockwork", "title": "A Cidade do Tempo", "number": 5, "subtitle": "Quando o relógio para, o céu esquece de amanhecer.", "musicTempo": 102, "musicTheme": "clockwork", "combatTempo": 132, "combatTheme": "clockwork-duel", "guideRobotId": "chrono", "customMusicUrl": "", "customCombatMusicUrl": ""}, {"id": "memory", "to": 42, "from": 35, "intro": "NEXA: O jardim preserva o que o mundo perdeu. Micélio encontrou uma raiz que fala; Aurélia protege a primeira lembrança. Reconecte as flores de cristal e escolha quais sinais levar para uma nova era.", "scene": "memory", "title": "O Jardim da Memória", "number": 6, "subtitle": "Algumas histórias só florescem quando são lembradas.", "musicTempo": 80, "musicTheme": "memory", "combatTempo": 124, "combatTheme": "memory-duel", "guideRobotId": "mycel", "customMusicUrl": "", "customCombatMusicUrl": ""}]'::jsonb,'public') on conflict(key) do update set value=excluded.value;
